-- Rollback marketplace seed data
-- Uses fixed UUIDs matching the up migration.

DELETE FROM skills WHERE id IN (
    'a0000001-0000-0000-0000-000000000001',
    'a0000001-0000-0000-0000-000000000002',
    'a0000001-0000-0000-0000-000000000003',
    'a0000001-0000-0000-0000-000000000004',
    'a0000001-0000-0000-0000-000000000005',
    'a0000001-0000-0000-0000-000000000006',
    'a0000001-0000-0000-0000-000000000007',
    'a0000001-0000-0000-0000-000000000008'
);

DELETE FROM mcp_servers WHERE id IN (
    'b0000001-0000-0000-0000-000000000001',
    'b0000001-0000-0000-0000-000000000002',
    'b0000001-0000-0000-0000-000000000003',
    'b0000001-0000-0000-0000-000000000004',
    'b0000001-0000-0000-0000-000000000005',
    'b0000001-0000-0000-0000-000000000006'
);

-- Remove the marketplace system user (only if it has no remaining owned resources)
DELETE FROM users WHERE id = 'c0000000-0000-0000-0000-000000000001'
    AND username = 'marketplace-system';
